const generateTicketNumber = () => {
  const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, ""); // YYYYMMDD
  const randomStr = Math.floor(1000 + Math.random() * 9000); // 4 digit random number
  return `PPID-${dateStr}-${randomStr}`;
};

